      email.deliver_now
    end

    assert_equal [ "david@37signals.com" ], email.to
    assert_equal "Your Fizzy data export is ready for download", email.subject
    assert_match %r{/users/#{export.user.id}/data_exports/#{export.id}}, email.body.encoded
  end
end
